// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        depositAmount = bound(depositAmount, 1, 1000 ether);
        withdrawAmount = bound(withdrawAmount, 1, depositAmount);

        address actor = address(0xBEEF);
        vm.deal(actor, depositAmount);

        vm.startPrank(actor);
        c.deposit{value: depositAmount}();
        c.withdraw(withdrawAmount);
        vm.stopPrank();

        // General rule: after a successful withdrawal, the user's remaining credit
        // is still fully collectible via refund(); the contract's ETH holdings equal
        // the recorded credit, so refund must succeed.
        vm.prank(actor);
        bool refundOk;
        try c.refund() { refundOk = true; } catch { refundOk = false; }

        assertTrue(refundOk);
    }
}
